"""Build synchronized frame inspection for the staged helmet identity repair."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def build():
    m=json.loads((HERE/'half-helmet-manifest.json').read_text());old=json.loads((ROOT/'character/veld-carry-half-turns-consistent-v1/helmet-manifest.json').read_text());previous={s['id']:s for s in old['states']};tracks=[]
    for s in m['states']:
        tracks.append({'id':s['id'].removeprefix('carry-turn-'),'after':s['frameFiles'],'before':['../veld-carry-half-turns-consistent-v1/'+p for p in previous[s['id']]['frameFiles']],'durations':s['frameDurationsMs']})
    html='''<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><meta charset="utf-8"><title>Veld master helmet turns</title>
<style>body{background:#202a30;color:#e1e7eb;font:16px system-ui;margin:24px}a{color:#8cc6e7}h1{font-size:27px}p{max-width:78ch;line-height:1.5}.masters{max-width:100%;height:auto}.row{display:flex;gap:20px;flex-wrap:wrap}.card{width:256px;background:#26353d;padding:10px;border-radius:8px}canvas{display:block}label,button,select{font:inherit}button,select{background:#344b57;color:white;border:1px solid #647f8e;padding:7px;border-radius:5px}.controls{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:18px 0}input{width:220px}small{color:#bdcbd4}</style>
<h1>Veld — master helmet turn family</h1><p>Master repair of all four helmet half-turns and eight quarter-turn directions. Original cardinal helmet components and master-derived intermediate heads; accepted body motion retained. Runtime cycles remain 680ms for half-turns and 800ms for quarters. Preview playback is slowed to one-third speed. Direction-specific collar registration now matches the masters; rear carry uses the same crown anchor. Installed locally; owner visual review remains open.</p>
<h2>Accepted directional masters</h2><img class="masters" src="accepted-master-reference.png" width="1024" alt="Accepted north, east, south and west helmet masters">
<div class="controls"><label>Turn <select id="turn"><option value="north-south">North → south</option><option value="south-north">South → north</option><option value="east-west">East → west</option><option value="west-east">West → east</option></select></label><button id="play">Pause</button><label>Frame <input id="slot" type="range" min="0" max="11" value="0"></label><span id="status">Loading frames</span></div>
<div class="row"><div class="card"><strong>Previous helmet</strong><canvas id="before" width="256" height="256"></canvas><small>Same crop, 3× head detail</small><canvas id="beforeHead" width="256" height="168"></canvas></div><div class="card"><strong>Master-derived helmet</strong><canvas id="after" width="256" height="256"></canvas><small>Same crop, 3× head detail</small><canvas id="afterHead" width="256" height="168"></canvas></div></div>
<p>Pause and scrub frame 7 of north → south to compare the former design switch. The before and after views always show the same body pose and animation slot. Station-scale playback:</p><canvas id="scales" width="500" height="165"></canvas>
<p><a href="../veld-consistency-audit-v2/cargo-handoffs.html">Idle/carry/turn handoffs</a> · <a href="carry-north-registration-v2.png">Rear carry alignment</a> · <a href="helmet-family-contact-v1.png">All quarter head views</a> · <a href="north-east-comparison-v5.png">North/east before and after</a> · <a href="../veld-consistency-audit-v2/">Selected full-set inventory</a></p>
<script>const tracks=TRACKS;const byId=Object.fromEntries(tracks.map(t=>[t.id,t]));let playing=true,time=0,last=performance.now(),manual=0;const turn=document.querySelector('#turn'),range=document.querySelector('#slot'),play=document.querySelector('#play'),status=document.querySelector('#status');
play.onclick=()=>{playing=!playing;play.textContent=playing?'Pause':'Play'};turn.onchange=()=>{time=0;manual=0;range.value=0};range.oninput=()=>{manual=Number(range.value);playing=false;play.textContent='Play';time=byId[turn.value].durations.slice(0,manual).reduce((a,b)=>a+b,0)};
async function load(files){return Promise.all(files.map(p=>new Promise((yes,no)=>{let im=new Image;im.onload=()=>yes(im);im.onerror=()=>no(new Error(p));im.src=p})))}
Promise.all(tracks.map(async t=>{t.b=await load(t.before);t.a=await load(t.after);t.total=t.durations.reduce((a,b)=>a+b,0)})).then(()=>{function draw(now){if(playing)time+=(now-last)/3;last=now;const t=byId[turn.value];let i=manual,v=time%t.total;if(playing){i=0;while(i<11&&v>=t.durations[i])v-=t.durations[i++];range.value=i;manual=i}status.textContent=`Frame ${i} / 11 · ${t.durations.slice(0,i).reduce((a,b)=>a+b,0)}ms`;
for(const [name,im] of [['before',t.b[i]],['after',t.a[i]]]){let c=document.querySelector('#'+name).getContext('2d');c.clearRect(0,0,256,256);c.drawImage(im,0,0);c=document.querySelector('#'+name+'Head').getContext('2d');c.clearRect(0,0,256,168);c.imageSmoothingEnabled=false;c.drawImage(im,96,60,68,56,26,0,204,168)}
let c=document.querySelector('#scales').getContext('2d');c.clearRect(0,0,500,165);let x=0;for(const h of [142,93,47]){c.drawImage(t.a[i],x,165-h,h,h);x+=h+25}requestAnimationFrame(draw)}requestAnimationFrame(draw)}).catch(e=>{status.textContent='Missing frame: '+e.message});</script>'''.replace('TRACKS',json.dumps(tracks,separators=(',',':')))
    (HERE/'index.html').write_text(html,encoding='utf-8')
if __name__=='__main__':build()
